import {concurrence,prepare} from './quantum.js';
import {tempoInfo} from './studio-tempo.js';
import {applyPreset} from './lab-presets.js';
const $=id=>document.getElementById(id);
function advanced(el,label){if(!el)return;const box=document.createElement('details');box.className='workflow-advanced';const s=document.createElement('summary');s.textContent='Advanced · '+label;el.before(box);box.append(s,el);return box;}
advanced($('music-circuit-panel'),'gate editor & inspection');advanced(document.querySelector('.tuning-panel'),'tuning & note mapping');advanced($('physics'),'equations & methods');
for(const card of document.querySelectorAll('.fx-card')){const p=[...card.querySelectorAll('.fx-range')].filter(e=>!e.querySelector('[data-fx-key="mix"]'));if(p.length){const box=advanced(p[0],'effect parameters');p.slice(1).forEach(e=>box.append(e));box.append(card.querySelector('.studio-buttons'));}}
const nmrSections=[...document.querySelectorAll('.studio-layout section.panel')],section=t=>nmrSections.find(s=>s.querySelector('h2')?.textContent===t);section('Prepare & relax each qubit').id='nmr-prepare-panel';section('T₂ vs T₂* & spin echo').id='nmr-decay-panel';
for(const q of [0,1]){const d=advanced($('s-theta'+q).parentElement,'initial state, T₁ & offsets');for(const k of ['phi','radius','t1','nu'])d.append($('s-'+k+q).parentElement);}
for(const id of ['s-purity','s-bloch-stat0','s-bloch-stat1'])advanced($(id),'physical numerical readout');
advanced(section('Choose your model & molecule'),'physical model & molecule');advanced(section('Translate physics into music'),'pitch mapping & listening route');const fid=section('Acquire the FID'),acq=advanced(fid.querySelector('.studio-fields'),'acquisition window, readout, J & echo');acq.append(fid.querySelector('.studio-check'));$('s-tauMs').closest('label').id='nmr-echo-controls';
const pop=document.createElement('p');pop.id='s-compact-populations';pop.className='compact-populations';$('s-bloch-note').before(pop);
const note=document.createElement('p');note.className='simulation-note';note.textContent='Changing a physical parameter creates a new simulation and stops the previous take. Apply & audition listens to the new result.';document.querySelector('.studio-layout').before(note);
const exps={music:[
 ['probability','How do probabilities change?','Change θ0 with product preparation and Z⊗Z readout. Keep seed, notes and tempo fixed. Exact probabilities and counts in a 16-shot sample are different quantities.','basic',['.state-panel','.measurement-panel']],
 ['phase','When can I hear relative phase?','In a product preparation, local phase leaves Z populations unchanged. X/Y readout can reveal interference. Quantum phase is not used directly as audio oscillator phase.','phase',['.state-panel','.measurement-panel']],
 ['bell','What changes with Bell correlations?','For the ideal Bell state, Z⊗Z and X⊗X are correlated; crossed bases differ. Local Bloch vectors vanish. Sound alone cannot certify entanglement.','bell',['.state-panel','.measurement-panel']],
 ['tuning','What changes only with tuning?','Only musical carrier frequencies change. A/B repeats the same outcomes and quantum state. Choose Just or Custom before comparing.','tuning',['.tuning-panel','.measurement-panel']]
],studio:[
 ['decay','How does decay sound?','T₂ is homogeneous transverse relaxation; T₂* also includes Gaussian static frequency spread. A/B holds musical BPM and pulse depth fixed. Study decay bypasses rhythmic masking.','both',['#nmr-prepare-panel','#nmr-decay-panel']],
 ['echo','What does spin echo restore?','A π pulse at τ refocuses static offsets at 2τ; irreversible T₂ loss remains. Simultaneous π pulses retain ZZ coupling. This lesson sets J/offsets to zero to isolate the envelope.','echo',['#nmr-prepare-panel','#nmr-decay-panel','#nmr-echo-controls']]
]};
const views={},tabs={music:new Map(),studio:new Map()},active={},homes=new Map();let mounted=[];
function restorePanels(){for(const p of mounted)homes.get(p).after(p);mounted=[];}
function view(b,mode){restorePanels();views[b].mode=mode;views[b].root.dataset.view=mode;views[b].workspace.hidden=mode!=='explore';for(const m of ['create','explore']){$(b+'-'+m).classList.toggle('active',m===mode);$(b+'-'+m).setAttribute('aria-pressed',String(m===mode));}if(mode==='explore'&&active[b])activate(b,active[b]);}
function feedback(){const m=tabs.music.get(active.music);if(m){const c=window.quantumLab.getSession().config,out=m.panel.querySelector('.experiment-feedback');out.textContent=active.music==='phase'?(c.cnot||c.circuit.length?'Additional gates/coupling are active. Load the reference to isolate local phase.':c.basis0==='Z'?'Phase can change while Z probabilities stay identical. Try basis X for q0.':'X/Y readout can reveal phase through changed probabilities; distinct mapped notes are needed to hear it.'):active.music==='bell'?`Current simulated pure-state concurrence: ${concurrence(prepare(c)).toFixed(3)}. A note sequence is not an entanglement test.`:'Change one parameter, compare, then export the chosen version.';}
 const n=tabs.studio.get(active.studio);if(n){const c=window.quantumStudio.getConfiguration(),t=tempoInfo(c);n.panel.querySelector('.experiment-feedback').textContent=active.studio==='echo'?`Echo at ${2*c.tauMs} ms. A/B holds ${t.bpm.toFixed(2)} BPM in both halves.`:`A/B: ${t.bpm.toFixed(2)} BPM, pulse ${c.tempo.rhythm?'on':'off'} with identical depth. Use transverse FID to study T₂ loss.`;}}
function activate(b,id){restorePanels();active[b]=id;for(const [k,t] of tabs[b]){t.panel.hidden=k!==id;t.button.setAttribute('aria-selected',String(k===id));t.button.tabIndex=k===id?0:-1;}const t=tabs[b].get(id);for(const selector of t.selectors){const p=document.querySelector(selector);if(!homes.has(p)){const h=document.createComment('Original panel location');p.before(h);homes.set(p,h);}t.panel.querySelector('.experiment-controls').append(p);mounted.push(p);}feedback();}
function open(b,id){const e=exps[b].find(e=>e[0]===id);if(!e)return;view(b,'explore');if(!tabs[b].has(id)){const [,title,text,preset,selectors]=e,tab=document.createElement('div');tab.className='experiment-tab';const button=document.createElement('button');button.id=b+'-experiment-tab-'+id;button.textContent=title;button.setAttribute('role','tab');button.setAttribute('aria-controls',b+'-experiment-'+id);button.onclick=()=>activate(b,id);const x=document.createElement('button');x.textContent='✕';x.className='experiment-close';x.setAttribute('aria-label','Close '+title);x.onclick=()=>{restorePanels();const t=tabs[b].get(id);t.tab.remove();t.panel.remove();tabs[b].delete(id);if(active[b]===id){active[b]=null;const next=tabs[b].keys().next().value;if(next){activate(b,next);tabs[b].get(next).button.focus();}else views[b].workspace.querySelector('.experiment-launcher button').focus();}else if(active[b])activate(b,active[b]);};tab.append(button,x);views[b].workspace.querySelector('.experiment-tabs').append(tab);
 const panel=document.createElement('section');panel.id=b+'-experiment-'+id;panel.className='experiment-panel';panel.dataset.experiment=id;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',button.id);panel.innerHTML='<h2></h2><p class="experiment-explanation"></p><button class="secondary-button load-experiment">Load this example</button><p class="experiment-replaces"></p><p class="experiment-feedback" role="status"></p><div class="experiment-controls"></div>';panel.querySelector('h2').textContent=title;panel.querySelector('.experiment-explanation').textContent=text;panel.querySelector('.experiment-replaces').textContent='Load explicitly replaces the settings listed in the example library. Previous settings are saved for Return before preset.';panel.querySelector('button').onclick=()=>window.quantumHistory.loadPreset(b,preset);views[b].workspace.querySelector('.experiment-content').append(panel);tabs[b].set(id,{tab,button,panel,selectors});}activate(b,id);}
for(const b of ['music','studio']){const root=$(b+'-workbench'),nav=document.createElement('div');nav.className='lab-view-switch';nav.setAttribute('role','group');nav.setAttribute('aria-label','Choose workflow');nav.innerHTML=`<button id="${b}-create" class="active" aria-pressed="true">Create sound</button><button id="${b}-explore" aria-pressed="false">Explore a phenomenon</button>`;root.prepend(nav);const workspace=document.createElement('section');workspace.id=b+'-experiments';workspace.className='experiment-workspace';workspace.hidden=true;workspace.innerHTML='<div class="experiment-launcher"></div><div class="experiment-tabs" role="tablist" aria-label="Open experiments"></div><div class="experiment-content"></div>';root.querySelector(b==='music'?'.workspace':'.studio-layout').before(workspace);views[b]={root,workspace,mode:'create'};for(const e of exps[b]){const button=document.createElement('button');button.className='secondary-button';button.textContent=e[1];button.onclick=()=>open(b,e[0]);workspace.querySelector('.experiment-launcher').append(button);}$(b+'-create').onclick=()=>view(b,'create');$(b+'-explore').onclick=()=>view(b,'explore');workspace.querySelector('.experiment-tabs').addEventListener('keydown',e=>{if(e.target.getAttribute('role')!=='tab')return;const t=[...tabs[b]],at=t.findIndex(([,t])=>t.button===e.target);let n;if(e.key==='ArrowRight')n=(at+1)%t.length;else if(e.key==='ArrowLeft')n=(at+t.length-1)%t.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=t.length-1;else return;e.preventDefault();activate(b,t[n][0]);t[n][1].button.focus();});
 const bar=document.createElement('div');bar.className='mobile-transport';bar.setAttribute('aria-label','Persistent audio controls');for(const [text,id] of b==='music'?[['Play','play'],['Stop','stop'],['WAV ↓','music-wav-quick'],['MP3 ↓','music-mp3-quick']]:[['Play','s-play'],['Stop','s-stop'],['WAV ↓','s-wav-quick'],['MP3 ↓','s-mp3-quick']]){const bt=document.createElement('button');bt.className=text==='Play'?'play-button':'secondary-button';bt.textContent=text;bt.onclick=()=>$(id).click();bar.append(bt);}root.append(bar);
}
document.addEventListener('lab:activated',e=>{restorePanels();const b=e.detail;if(views[b]?.mode==='explore'&&active[b])activate(b,active[b]);});for(const e of ['music:configuration','studio:configuration'])document.addEventListener(e,feedback);
Object.assign(window.quantumWorkflow,{openExperiment:open,setView:view});
// Guide navigation opens the relevant experiment after explicit loading.
for(const button of document.querySelectorAll('[data-lesson]'))button.addEventListener('click',()=>open('music',{basic:'probability',phase:'phase',bell:'bell',tuning:'tuning'}[button.dataset.lesson]));document.querySelector('[data-guide-section="echo"]').addEventListener('click',()=>open('studio','echo'));
const card=document.createElement('section');card.className='guide-card';card.innerHTML='<h2>Create, explore, keep a version</h2><p>Create sound keeps basic controls visible. Explore opens a closable experiment with its own explanation. Switching views keeps the same settings. Advanced reveals detailed controls locally.</p><p>The complete pipeline shows slider-controlled preparation and added gates. The example library lists the settings each preset replaces, stores a previous snapshot, and offers Return before preset. Undo/Redo covers configuration edits; a complete slider drag is one action.</p><p>Comparison details explains the isolated change, fixed settings and observation. Decay A/B freezes music rhythm. Preview only keeps frozen auditions for independent export without changing the main circuit. The preview list is temporary for this page load; export JSON for a portable current session.</p><p>WAV + explanation TXT produces two downloads. TXT is also available separately under Audio options or Preview. Include FX tail shows total duration with a 12 s cap; Trim uses a 0.30 s release. Seamless looping is not guaranteed. Live automation and previous live effect memory are not recorded in a frozen export.</p>';$('guide-workbench').prepend(card);const replay=document.createElement('button');replay.className='secondary-button';replay.textContent='Replay NMR guide';replay.onclick=()=>window.quantumUI.openTour('studio');$('guide-replay').after(replay);window.quantumStudio.compute();
